[
 {
  "number": "1",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "1. A method for correlating a plurality of messages conforming to different protocols and associated with a common communication call in a communication network, comprising the steps of: extracting an information from a message; extracting a protocol specific identifier to identify the protocol to which the message conforms, such that all the messages conforming to the same protocol have the same protocol specific identifier; forming a plurality of protocol specific queues, such that messages having same protocol specific identifier are in same queue; forming a correlation ID using the information extracted from the message and the protocol specific identifier of the message, such that the messages associated with the same communication call have same correlation ID; and forming a call specific queue comprising of messages extracted from the plurality of protocol specific queues associated with the same common communication call and having same correlation ID."
 },
 {
  "number": "2",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "2. The method according to claim 1, further comprising the processing of messages from the call specific queue with FIFO criterion."
 },
 {
  "number": "3",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "3. The method according to claim 1, wherein the message is a telecom message in a telecommunication network."
 },
 {
  "number": "4",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "4. The method according to claim 1, wherein the protocols are telecom and messaging protocols from a list including a SIP, a HTTP, a MGCP, a Diameter, a CAP, a MAP, an INAP, a SMTP, a SMPP protocols or a combination thereof."
 },
 {
  "number": "5",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "5. The method according to claim 1, wherein the message includes a data."
 },
 {
  "number": "6",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "5"
  ],
  "text": "6. The method according to claim 5, wherein the protocol includes a format of the data."
 },
 {
  "number": "7",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "7. The method according to claim 1, wherein the step of extracting information and the protocol specific identifier from the message is done based on a pre-defined set of rules."
 },
 {
  "number": "8",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "7"
  ],
  "text": "8. The method according to claim 7, wherein the pre-defined set of rules are different for different protocols."
 },
 {
  "number": "9",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "9. The method according to claim 1, wherein the step of forming the correlation ID is based on a pre-defined set of rules."
 },
 {
  "number": "10",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "9"
  ],
  "text": "10. The method according to claim 9, wherein the pre-defined set of rules are different for different protocols."
 },
 {
  "number": "11",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "11. The method according to claim 1, wherein the correlation ID includes a plurality of call context specific identifiers."
 },
 {
  "number": "12",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1",
   "1"
  ],
  "text": "12. The method according to claim 1, wherein the correlation ID is saved in a memory of a system where the method of claim 1 is applied."
 },
 {
  "number": "13",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "13. The method according to claim 1, further comprising mapping of the protocol specific identifiers from each of the different protocols with the correlation ID."
 },
 {
  "number": "14",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "13"
  ],
  "text": "14. The method according to claim 13, further comprising routing the subsequent messages by identifying the protocol specific identifier and using the mapping of the protocol specific identifiers with the correlation ID."
 }
]

[
 {
  "number": "1",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "1) A superconducting quantum interference device sensor system, comprising: a) a magnetic pulser, adapted to apply a uniform magnetizing pulse field to a transplanted organ of a patient placed on a measurement stage; and b) a remnant magnetic field detector, adapted to detect and image the residual magnetic field produced by a plurality of antibody-labeled magnetic nanoparticles injected into the patient for specific binding to T cells."
 },
 {
  "number": "2",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "2) The system of claim 1, wherein the remnant magnetic field detector provides an image of the nanoparticles bound to the T cells on the transplanted organ of the patient."
 },
 {
  "number": "3",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "3) A method for nonsurgical determination of organ transplant condition, comprising: a) providing a superconducting quantum interference device sensor system comprising: i) a magnetic pulser, adapted to apply a uniform magnetizing pulse field to a transplanted organ of a patient, and ii) a remnant magnetic field detector, adapted to detect, measure, image, or a combination thereof, the residual magnetic field produced by the applied pulsed field; b) injecting a plurality of magnetic nanoparticles, each labeled with a targeting agent such as an antibody or peptide, into the patient for specific binding to the transplanted organ; c) applying the uniform magnetizing pulse field to magnetize the nanoparticles injected into the patient; and d) detecting the residual magnetic field of the magnetized nanoparticles thereby providing an image of the nanoparticles bound to the transplanted organ of the patient."
 },
 {
  "number": "4",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "3"
  ],
  "text": "4) The method of claim 3, wherein the magnetic pulser comprises a pair of Helmholtz coils."
 },
 {
  "number": "5",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "3"
  ],
  "text": "5) The method of claim 3, wherein the remnant magnetic field detector comprises an array of gradiometers."
 },
 {
  "number": "6",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "3"
  ],
  "text": "6) The method of claim 3, wherein the remnant magnetic field detector comprises an imaging means that solves an electromagnetic inverse problem."
 },
 {
  "number": "7",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "3"
  ],
  "text": "7) The method of claim 3, wherein the transplanted organ comprises a kidney."
 },
 {
  "number": "8",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "3"
  ],
  "text": "8) The method of claim 3, wherein the magnetic nanoparticles are labeled with an antibody that specifically binds to T-cells present in or near the transplanted organ."
 },
 {
  "number": "9",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "3"
  ],
  "text": "9) The method of claim 3, wherein the magnetic nanoparticle comprises a magnetic core coated with a biocompatible coating to which is attached at least one specific antibody."
 },
 {
  "number": "10",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "9"
  ],
  "text": "10) The method of claim 9, wherein the magnetic core comprises a ferromagnetic material."
 },
 {
  "number": "11",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "10"
  ],
  "text": "11) The method of claim 10, wherein the ferromagnetic material comprises iron oxide."
 },
 {
  "number": "12",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "9"
  ],
  "text": "12) The method of claim 9, wherein the magnetic core is less than 30 nanometers in diameter."
 },
 {
  "number": "13",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "9"
  ],
  "text": "13) The method of claim 9, wherein the biocompatible coating comprises Dextran, carboxyl, or amine."
 },
 {
  "number": "14",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "9"
  ],
  "text": "14) The method of claim 9, wherein the at least one specific antibody comprises a T cell specific antibody."
 },
 {
  "number": "15",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "14"
  ],
  "text": "15) The method of claim 14, wherein the T cell specific antibody comprises a CD antibody."
 },
 {
  "number": "16",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "16) A method to calibrate a superconducting quantum interference device sensor system, comprising: a) providing a superconducting quantum interference device sensor system comprising: i) a magnetic pulser, adapted to apply a uniform magnetizing pulse field to a phantom, comprising a known amount of antibody-labeled magnetic nanoparticles, placed on a measurement stage, wherein the antibody-labeled magnetic nanoparticles are bound to a specific T cell line, and ii) a remnant magnetic field detector, adapted to detect and image a residual magnetic field produced by the applied pulsed field; b) applying the uniform magnetizing pulse field to magnetize the nanoparticles in the phantom placed on the measurement stage; and c) detecting the residual magnetic field of the magnetized nanoparticles thereby providing a sensitivity calibration for a organic transplant model."
 },
 {
  "number": "17",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "16"
  ],
  "text": "17) A method as in claim 16, wherein the antibody-labeled magnetic nanoparticle comprises a magnetic core that comprises a ferromagnetic material."
 },
 {
  "number": "18",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "17"
  ],
  "text": "18) A method as in claim 17, wherein the ferromagnetic material comprises iron oxide."
 },
 {
  "number": "19",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "16"
  ],
  "text": "19) A method as in claim 16, wherein the antibody-labeled magnetic nanoparticle comprises a magnetic core that is less than 30 nanometers in diameter."
 },
 {
  "number": "20",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "16"
  ],
  "text": "20) A method as in claim 16, wherein antibody-labeled magnetic nanoparticle comprises a biocompatible coating comprising Dextran, carboxyl, or amine."
 },
 {
  "number": "21",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "16"
  ],
  "text": "21) A method as in claim 16, wherein the T cell specific antibody comprises a CD antibody."
 }
]

[
 {
  "number": "1",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "1. A mobile terminal, comprising: a touchscreen configured to sense touch inputs; and a controller configured to determine whether a touch input is an input using a finger of a user, wherein, when the touch input is determined to be a touch input using a user's finger and a function associated with the touch input requires authentication, a prescribed user interface for authentication is provided, the prescribed user interface for authentication when the touch input is an input using a user's finger being different than a user interface for authentication when the touch input is not an input using a user's finger."
 },
 {
  "number": "2",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "2. The mobile terminal of claim 1, further comprising a fingerprint sensor integrated with the touchscreen and configured to recognize a fingerprint, wherein fingerprint information of the user is acquired through the fingerprint sensor when the touch input is a touch input using the user's finger and authentication is necessary, and the function intended by the touch input is executed when the acquired fingerprint information corresponds to pre-registered fingerprint information."
 },
 {
  "number": "3",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "2"
  ],
  "text": "3. The mobile terminal of claim 2, wherein the touchscreen comprises a touch IC including a plurality of Tx lines, a plurality of Rx lines intersecting the Tx lines and touch sensors formed at intersections of the Tx lines and the Rx lines, wherein the touch IC is configured to acquire a fingerprint image corresponding to touch sensors touched by the user's finger from among the touch sensors."
 },
 {
  "number": "4",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "3"
  ],
  "text": "4. The mobile terminal of claim 3, wherein the controller is configured to recognize coordinates of a touch point corresponding to the touch input and to acquire the fingerprint image through the touch IC when fingerprint authentication is necessary to execute an application corresponding to the recognized coordinates."
 },
 {
  "number": "5",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "2"
  ],
  "text": "5. The mobile terminal of claim 2, wherein the controller is configured to provide, on the touchscreen, a notification indicating that acquisition of the fingerprint information of the user through the fingerprint sensor is in progress."
 },
 {
  "number": "6",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "2"
  ],
  "text": "6. The mobile terminal of claim 2, wherein the controller is configured to display a fingerprint input window on the touchscreen and to acquire the fingerprint information of the user through the fingerprint sensor when a finger of the user touches the fingerprint input window."
 },
 {
  "number": "7",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "6"
  ],
  "text": "7. The mobile terminal of claim 6, wherein the fingerprint sensor is activated when the fingerprint input window is displayed."
 },
 {
  "number": "8",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "2"
  ],
  "text": "8. The mobile terminal of claim 2, wherein the fingerprint sensor is activated when the touch input is determined to be a touch input using a user's finger."
 },
 {
  "number": "9",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "2"
  ],
  "text": "9. The mobile terminal of claim 2, wherein the fingerprint sensor is activated when the touch input is determined to be a touch input using a user's finger and the function associated with the touch input requires authentication."
 },
 {
  "number": "10",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "10. The mobile terminal of claim 1, wherein the user interface for authentication when the touch input is not an input using the user's finger is a window for inputting a predetermined pattern for authentication on the touchscreen."
 },
 {
  "number": "11",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "10"
  ],
  "text": "11. The mobile terminal of claim 10, wherein the touch input is an input using a stylus pen."
 },
 {
  "number": "12",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "12. The mobile terminal of claim 1, wherein the user interface for authentication when the touch input is not an input using the user's finger is a window for inputting a password or passcode."
 },
 {
  "number": "13",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "13. The mobile terminal of claim 1, wherein, when the touch input is recognized as including a touch by the user's finger and a part of the user's body other than the finger, the controller is configured to process the touch input for only the touch by the user's finger as a normal touch input."
 },
 {
  "number": "14",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "14. The mobile terminal of claim 1, wherein functions requiring authentication include at least one of a function to unlock a locked screen, a function to unlock a locked application or a function to unlock a locked touchscreen while turning on the touchscreen from an off state."
 },
 {
  "number": "15",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "15. A method for controlling a mobile terminal, comprising: receiving touch input applied to a touchscreen; processing the touch input to determine whether the touch input is an input using a finger of a user; and providing a user interface for authentication when a function associated with the touch input requires authentication, wherein the user interface for authentication when the touch input is an input using the user's finger is different than a user interface necessary for authentication when the touch input is not an input using a user's finger."
 },
 {
  "number": "16",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "15"
  ],
  "text": "16. The method of claim 15, further comprising: acquiring fingerprint information of the user through a fingerprint sensor integrated with the touchscreen when the touch input is an input using the user's finger and authentication is necessary; and executing the function intended by the touch input when the acquired fingerprint information corresponds to pre-registered fingerprint information."
 },
 {
  "number": "17",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "16"
  ],
  "text": "17. The method of claim 16, wherein the fingerprint sensor is activated when the touch input is determined to be a touch input using a user's finger and the function associated with the touch input requires authentication."
 },
 {
  "number": "18",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "15"
  ],
  "text": "18. The method of claim 15, wherein the user interface for authentication when the touch input is not an input using a user's finger is a window for inputting a predetermined pattern for authentication on the touchscreen."
 },
 {
  "number": "19",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "15"
  ],
  "text": "19. The method of claim 15, wherein the user interface for authentication when the touch input is not an input using a user's finger is a window for inputting a password or passcode."
 },
 {
  "number": "20",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "15"
  ],
  "text": "20. The method of claim 15, wherein, when the touch input is recognized as including a touch by the user's finger and a part of the user's body other than the finger, processing the touch input for only the touch by the user's finger as a normal touch input."
 }
]

[
 {
  "number": "1",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "1. An access node for digital subscriber line (DSL) communication comprising: a transceiver configured to couple a subscriber line; and a control entity coupled to the transceiver, wherein the control entity is configured to: receive a request to switch to a nominal asymmetry ratio between an upstream data rate and a downstream data rate after initialization of the subscriber line; determine a flexible time period value based on the nominal asymmetry ratio, wherein the flexible time period is used to define a time division duplexing (TDD) frame structure; and forward a message that comprises the flexible time period value to the transceiver, wherein the transceiver is configured to: transmit an upstream transmission using the TDD frame structure over the subscriber line; and receive a downstream transmission using the TDD frame structure over the subscriber line."
 },
 {
  "number": "2",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "2. The access node of claim 1, wherein the transceiver is further configured to transmit the message to a remote site located at the opposite end of the subscriber line, and wherein the transceiver is further configured to transmit the message multiple times within a TDD frame."
 },
 {
  "number": "3",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "3. The access node of claim 1, wherein the transceiver is further configured to switch to the nominal asymmetry ratio at a predefined TDD frame."
 },
 {
  "number": "4",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "4. The access node of claim 1, wherein the TDD frame structure comprises a fixed downstream time period and a fixed upstream time period, wherein the fixed downstream time period may indicate the minimum time period allocated for the downstream transmission, and wherein the fixed upstream time period may indicate the minimum time period allocated for the upstream transmission."
 },
 {
  "number": "5",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "4"
  ],
  "text": "5. The access node of claim 4, wherein the fixed downstream time period is used by a receiver at a customer premise equipment (CPE) for signal-to-noise ratio (SNR) measurements, and wherein the upstream time period is used by the receiver at the access node for SNR measurements, and wherein the fixed upstream time period is used by the control entity at the access node for updating a plurality of pre-coder coefficients in the transceiver, and wherein the fixed downstream time period is used by the control entity at the access node for updating a plurality of canceler coefficients in the transceiver."
 },
 {
  "number": "6",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "4"
  ],
  "text": "6. The access node of claim 4, wherein the TDD frame structure comprises a flexible time period, and wherein the length of the flexible time period is set by the flexible time period value."
 },
 {
  "number": "7",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "6"
  ],
  "text": "7. The access node of claim 6, wherein a portion of the flexible time period is allocated for the downstream transmission, and wherein another portion of the flexible time period is allocated for the upstream transmission."
 },
 {
  "number": "8",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "7"
  ],
  "text": "8. The access node of claim 7, wherein allocating the portion of the flexible time period for downstream transmission is determined by the nominal asymmetry ratio."
 },
 {
  "number": "9",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "7"
  ],
  "text": "9. The access node of claim 7, wherein the downstream transmission uses no more than the portion of the flexible time period allocated for the downstream transmission."
 },
 {
  "number": "10",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "10. The access node of claim 1, wherein the control entity is further configured to determine the flexible time period value according to the nominal asymmetry ratio, a fixed downstream time period value, and a fixed upstream time period value, wherein the fixed downstream time period value is based on a minimum data rate for the downstream transmission, and wherein the fixed upstream time period value is based on a minimum data rate for the upstream transmission."
 },
 {
  "number": "11",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "10"
  ],
  "text": "11. The access node of claim 10, wherein the flexible time period value, the fixed downstream time period value, and the fixed upstream time period value remain the same until the control entity receives another request to switch to a different nominal asymmetry ratio."
 },
 {
  "number": "12",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "1"
  ],
  "text": "12. The access node of claim 1 further comprising a management information base (MIB), wherein the MIB provides the nominal asymmetry ratio to the control entity."
 },
 {
  "number": "13",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "13. An access node for digital subscriber line (DSL) communication over a plurality of subscriber lines comprising: a control entity; a transceiver coupled to the control entity, wherein the transceiver is configured to: determine a number of active symbols to be transmitted within a time division duplexing (TDD) frame; and transmit a downstream transmission portion of the TDD frame via a first subscriber line using the number of active symbols to be transmitted, wherein the TDD frame comprises a plurality of symbols, wherein the number of active symbols to be transmitted is no more than a total number of symbols allocated for the downstream portion of the TDD frame, and wherein a downstream transmitter of the first subscriber line is powered off after the transmission of the active symbols during the downstream transmission portion of the TDD frame."
 },
 {
  "number": "14",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "13"
  ],
  "text": "14. The apparatus of claim 13, wherein the number of active symbols to be transmitted in a TDD frame are set during the showtime state of the first subscriber line, wherein the showtime state references the time period after initializing the first subscriber line, and wherein a vectoring mechanism is used to cancel crosstalk between the first subscriber line and a second subscriber line."
 },
 {
  "number": "15",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "13"
  ],
  "text": "15. The apparatus of claim 13, wherein each of the symbols comprise a plurality of bits, and wherein the number of active symbols to be transmitted within a time division duplexing (TDD) frame is determined according to the traffic volume of the subscriber line, the total length of the TDD frame, the number of bits per symbol, and the number of symbols transmitted per second."
 },
 {
  "number": "16",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "13"
  ],
  "text": "16. The apparatus of claim 13, wherein the control entity is configured forward information to a second subscriber line that the downstream transmitter of the first subscriber line will power off after the transmission of the active symbols during the downstream transmission portion of the TDD frame."
 },
 {
  "number": "17",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "16"
  ],
  "text": "17. The apparatus of claim 16, wherein the control entity is further configured to receive information from the second subscriber line that a transmitter of the second subscriber line will power off, and wherein the transceiver does not increase the number of active symbols transmitted during the downstream portion of the TDD frame when the transmitter of the second subscriber line powers off."
 },
 {
  "number": "18",
  "status": "",
  "type": "independent",
  "depends_on": [],
  "text": "18. A method for digital subscriber line (DSL) communication over a plurality of subscriber lines in the showtime state, wherein the method comprises: receiving a message that sets a number of active symbols within a TDD frame; and transmitting an upstream transmission portion of the TDD frame over a first subscriber line, wherein the upstream transmission portion of the TDD frame comprises an awake window and a sleep window, wherein the length of the awake window and the sleep window are set by the number of active symbols, and wherein a transmitter of the first subscriber line powers off during the sleep window."
 },
 {
  "number": "19",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "18"
  ],
  "text": "19. The method of claim 18 further comprising transmitting an acknowledgement message after receiving the message that sets the number of active symbols within the TDD frame."
 },
 {
  "number": "20",
  "status": "",
  "type": "dependent",
  "depends_on": [
   "19"
  ],
  "text": "20. The method of claim 19, wherein the message maps the location of the awake window and the sleep window within the upstream transmission portion of the TDD frame."
 }
]

[
 {
  "number": "1",
  "status": "",
